        'Sai — phương án <code>Bông gòn</code> không phù hợp với thực tế và bài học. Đáp án đúng là <b>Xi măng, cát, đá, thép</b> vì bê tông cốt thép gồm xi măng, cát, đá kết hợp với thép.',
