        'Sai — lựa chọn <code>Vải bông</code> không chính xác — không khớp với kiến thức bài học. Đáp án đúng là <b>Đất sét nung</b> vì gạch ngói truyền thống làm từ đất sét, qua quá trình nung ở nhiệt độ cao.',
