        'Sai — lựa chọn <code>Để đẹp mắt</code> không chính xác — không khớp với kiến thức bài học. Đáp án đúng là <b>Để bảo vệ đầu khỏi vật rơi</b> vì mũ bảo hộ bảo vệ thợ xây khỏi nguy cơ vật rơi từ trên cao.',
