        'Sai — <code>10°C cho lạnh</code> chưa đúng với yêu cầu của câu hỏi. Đáp án đúng là <b>Khoảng 26–28°C để tiết kiệm điện</b> vì 26–28°C là mức tiết kiệm điện và tốt cho sức khỏe.',
        'Sai — phương án <code>40°C cho nóng</code> không phù hợp với thực tế và bài học. Đáp án đúng là <b>Khoảng 26–28°C để tiết kiệm điện</b> vì 26–28°C là mức tiết kiệm điện và tốt cho sức khỏe.',
