        'Sai — <code>Tăng giá điện</code> chưa đúng với yêu cầu của câu hỏi. Đáp án đúng là <b>Giảm phát thải khí nhà kính, bảo vệ tài nguyên</b> vì dùng ít năng lượng → giảm đốt nhiên liệu hóa thạch → giảm phát thải.',
        'Sai — phương án <code>Không có tác dụng gì</code> không phù hợp với thực tế và bài học. Đáp án đúng là <b>Giảm phát thải khí nhà kính, bảo vệ tài nguyên</b> vì dùng ít năng lượng → giảm đốt nhiên liệu hóa thạch → giảm phát thải.',
