        '<ul><li><b>Mặt trời</b>: pin mặt trời → điện.</li><li><b>Gió</b>: tuabin gió → điện.</li><li><b>Nước</b>: thủy điện.</li><li><b>Sinh khối, địa nhiệt</b>.</li></ul>',
        '<b>Năng lượng KHÔNG tái tạo</b> (hóa thạch): <code>than, dầu mỏ, khí đốt</code> — có hạn và gây ô nhiễm khi đốt.',
