        'Sai — lựa chọn <code>Chạy lại cầm tay nạn nhân ngay</code> không chính xác — không khớp với kiến thức bài học. Đáp án đúng là <b>Ngắt nguồn điện (cầu dao/aptomat)</b> vì phải ngắt nguồn điện trước, sau đó mới cứu nạn để không bị giật theo.',
        'Đúng — Phải ngắt nguồn điện trước, sau đó mới cứu nạn để không bị giật theo.',
