        'Sai — phương án <code>Dùng kéo cắt dây</code> không phù hợp với thực tế và bài học. Đáp án đúng là <b>Cầm phần nhựa của phích, không kéo dây</b> vì cầm phần nhựa của phích rút ra, không kéo dây.',
