        'Sai — <code>Thêm đường nhiều</code> không phù hợp với nội dung câu hỏi. Đáp án đúng là <b>Giảm độ ẩm để vi sinh vật khó phát triển</b> vì vi sinh vật cần nước; giảm độ ẩm giúp ức chế chúng.',
        'Sai — lựa chọn <code>Đông cứng nước</code> không chính xác — không khớp với kiến thức bài học. Đáp án đúng là <b>Giảm độ ẩm để vi sinh vật khó phát triển</b> vì vi sinh vật cần nước; giảm độ ẩm giúp ức chế chúng.',
        'Sai — <code>Đập dập</code> chưa đúng với yêu cầu của câu hỏi. Đáp án đúng là <b>Giảm độ ẩm để vi sinh vật khó phát triển</b> vì vi sinh vật cần nước; giảm độ ẩm giúp ức chế chúng.',
