        '<ul><li>⚠️ Nắp <b>phồng lên</b>, hộp bị <b>méo, gỉ sét</b>.</li><li>⚠️ Mở ra có <code>mùi hôi, đổi màu</code>, sủi bọt bất thường.</li><li>⚠️ Quá <code>hạn sử dụng</code>.</li></ul>',
        '<b>Nguy hiểm chính</b>: vi khuẩn <code>Clostridium botulinum</code> sinh khí làm phồng hộp, tiết ra <b>độc tố botulinum</b> — một trong các <i>chất độc thần kinh mạnh nhất</i>, có thể <b>gây tử vong</b> chỉ với liều cực nhỏ. Tuyệt đối phải <b>vứt bỏ</b>.',
