        'Sai — phương án <code>Đường nóng chảy</code> không phù hợp với thực tế và bài học. Đáp án đúng là <b>Dầu/mỡ nóng</b> vì chiên/rán dùng dầu nóng để làm chín và tạo lớp vỏ giòn.',
