        'Đúng — Dầu chiên đi chiên lại sinh chất có hại cho sức khỏe.',
        'Sai — <code>Vớt sạch cặn dầu</code> chưa đúng với yêu cầu của câu hỏi. Đáp án đúng là <b>Dùng dầu đã chiên đi chiên lại nhiều lần</b> vì dầu chiên đi chiên lại sinh chất có hại cho sức khỏe.',
