        'Sai — phương án <code>Đắt nhất có thể</code> không phù hợp với thực tế và bài học. Đáp án đúng là <b>Vừa người mặc, phù hợp hoàn cảnh, hài hòa màu sắc</b> vì đẹp = vừa, phù hợp và hài hòa, không chỉ ở giá tiền.',
