        'Sai — lựa chọn <code>Tắt nguồn hoàn toàn</code> không chính xác — không khớp với kiến thức bài học. Đáp án đúng là <b>Giữ ấm (Warm)</b> vì khi đạt nhiệt độ chín, nồi chuyển sang giữ ấm tự động.',
