        'Sai — lựa chọn <code>Nồi thủy tinh</code> không chính xác — không khớp với kiến thức bài học. Đáp án đúng là <b>Nồi có đáy nhiễm từ (gang, inox 430…)</b> vì cần đáy nhiễm từ để sinh dòng cảm ứng.',
