        'Sai — lựa chọn <code>Lau khi bếp còn rất nóng</code> không chính xác — không khớp với kiến thức bài học. Đáp án đúng là <b>Đợi nguội rồi lau bằng khăn ẩm và dung dịch chuyên dụng</b> vì mặt kính bếp từ dễ nứt khi sốc nhiệt và xước khi cào…',
