        '<b>"Điện ma" (phantom power)</b> — điện tiêu thụ ngầm:',
        '<ul><li>👻 Thiết bị ở chế độ <code>standby</code> (đèn đỏ chờ) vẫn tốn điện.</li><li>📊 Ước tính ~5-10% hóa đơn điện đến từ "điện ma".</li><li>🔌 <b>Rút phích</b>: tivi, máy tính, sạc điện thoại khi không dùng.</li><li>🔘 Dùng <b>ổ cắm có công tắc</b> tiện tắt nguồn cụm thiết bị.</li></ul>',
        '<b>Mẹo</b>: tạo thói quen <i>kiểm tra trước khi đi ngủ</i> — tắt hết đèn, rút phích các thiết bị không cần.',
